mapper.select:
SELECT id, series_id, display_title, duration_seconds, vid
FROM local_video_episode
WHERE vid = #{vid}

SELECT e.id, e.series_id, e.display_title, e.vid
FROM local_video_episode e
INNER JOIN video v ON v.vid = e.vid
WHERE e.series_id = #{seriesId}
  AND e.id > #{afterId}
  AND v.status = 1
  AND v.deleted_at IS NULL
  AND (v.visibility = 0 OR v.uid = #{uid})
ORDER BY e.id
LIMIT #{limit}
